		id: "popup1",
		type: "wframePopup",
		width: "230px",
		height: "250px",
		top: "130px",
		left: "200px",
		popupName: "testPopup",
		modal: true,
		windowMoveType: "overflow",
		resizable: true,
		status: true,
		menubar: false,
		scrollbars: false,
		title: false,
		windowDragMove: true,
		useControl: true,
		controls: { minimize: false, maximize: false, close: true }
	};
	$p.openPopup("/sample/common_link/p_openPopup_windowDragMove_WESE-235_(WSQ-5279)_main_popup.xml", options);
